FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 085: a cone side replaced by a cylinder, isoparametric curves and parameters of full tori, a variable fillet at a corner. Generated by tools/fixtures/gen-batch-085.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function round6(v) returns array
{
    return [roundToPrecision(v[0] / millimeter, 6), roundToPrecision(v[1] / millimeter, 6), roundToPrecision(v[2] / millimeter, 6)];
}

function dir6(v) returns array
{
    return [roundToPrecision(v[0], 6), roundToPrecision(v[1], 6), roundToPrecision(v[2], 6)];
}

// Each face of a body: its area and its surface's type.
function faceProbe(context is Context, body is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qOwnedByBody(body, EntityType.FACE)))
    {
        var entry = { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6) };
        try
        {
            entry["type"] = evSurfaceDefinition(context, { "face" : face, "returnBSplinesAsOther" : true }).surfaceType;
        }
        catch (error)
        {
            entry["type"] = "failed";
        }
        out = append(out, entry);
    }
    return out;
}

// Three points along each edge of a body (its ends and middle, in its own parameter).
function edgePoints(context is Context, body is Query) returns array
{
    var out = [];
    for (var edge in evaluateQuery(context, qOwnedByBody(body, EntityType.EDGE)))
    {
        const lines = evEdgeTangentLines(context, { "edge" : edge, "parameters" : [0, 0.5, 1], "arcLengthParameterization" : false });
        out = append(out, mapArray(lines, function(l) { return round6(l.origin); }));
    }
    return out;
}

// A torus face's coordinate system and its points at the corners and middle of its parameter range.
function torusProbe(context is Context, face is Query) returns map
{
    const s = evSurfaceDefinition(context, { "face" : face });
    const cs = s.coordSystem;
    const planes = evFaceTangentPlanes(context, { "face" : face, "parameters" : [vector(0, 0), vector(0.25, 0), vector(0, 0.25), vector(0.5, 0.5)] });
    return { "origin" : round6(cs.origin), "xAxis" : dir6(cs.xAxis), "zAxis" : dir6(cs.zAxis),
             "points" : mapArray(planes, function(p) { return round6(p.origin); }) };
}

// replace-face: a cone frustum (radius 10 to 6, 20 tall): its side replaced by a coaxial cylinder of radius 8
export function c001(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(s1, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(10, 0) * millimeter });
    skLineSegment(s1, "l2", { "start" : vector(10, 0) * millimeter, "end" : vector(6, 20) * millimeter });
    skLineSegment(s1, "l3", { "start" : vector(6, 20) * millimeter, "end" : vector(0, 20) * millimeter });
    skLineSegment(s1, "l4", { "start" : vector(0, 20) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(s1);
    const axis = newSketchOnPlane(context, id + "axis", { "sketchPlane" : plane(vector(0, 0, -50) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skSolve(axis);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "s1"), "axis" : qCreatedBy(id + "axis", EntityType.EDGE), "fullRevolve" : true });
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(s2, "c1", { "center" : vector(0, 0) * millimeter, "radius" : 8 * millimeter });
    skSolve(s2);
    extrude(context, id + "tool", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "s2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter, "oppositeDirection" : false });
    replaceFace(context, id + "replace1", { "replaceFaces" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.CONE), "templateFace" : qOwnedByBody(qBodyType(qCreatedBy(id + "tool", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "oppositeSense" : false, "offset" : 0 * millimeter });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)) };
}

// isoparametric-curve: four isoparametric curves in the U direction on a full torus about z, and its parameters
export function c002(context is Context, id is Id)
{
    const profile = newSketchOnPlane(context, id + "profile", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skCircle(profile, "c1", { "center" : vector(20, 0) * millimeter, "radius" : 5 * millimeter });
    skSolve(profile);
    const axis = newSketchOnPlane(context, id + "axis", { "sketchPlane" : plane(vector(0, 0, -50) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skSolve(axis);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "profile"), "axis" : qCreatedBy(id + "axis", EntityType.EDGE), "fullRevolve" : true });
    isoparametricCurve(context, id + "curve1", { "face" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.TORUS), "directionType" : DirectionType.U_DIRECTION, "equalSpacing" : true, "nCurves" : 4 });
    return { "torus" : torusProbe(context, qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.TORUS)), "periodicity" : [evFacePeriodicity(context, { "face" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.TORUS) }), evFacePeriodicity(context, { "face" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.TORUS), "trimmed" : false })], "curves" : edgePoints(context, qCreatedBy(id + "curve1", EntityType.BODY)) };
}

