// fillet: a variable conic fillet (rho 0.7) of a block's top front and top right edges, meeting at a corner: 2 mm at the far ends, 4 mm at the corner
export function c005(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 12 * millimeter });
    fillet(context, id + "fillet1", { "entities" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(20, 0, 12) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(40, 15, 12) * millimeter)]), "radius" : 3 * millimeter, "nonCircularRadius" : 3 * millimeter, "isVariable" : true, "crossSection" : FilletCrossSection.CONIC, "rho" : 0.7, "smoothTransition" : true, "vertexSettings" : [{ "vertex" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(0, 0, 12) * millimeter), "vertexRadius" : 2 * millimeter, "variableRho" : 0.7 }, { "vertex" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(40, 0, 12) * millimeter), "vertexRadius" : 4 * millimeter, "variableRho" : 0.7 }, { "vertex" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(40, 30, 12) * millimeter), "vertexRadius" : 2 * millimeter, "variableRho" : 0.7 }] });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)) };
}
